import tarfile
import os
class Project:
    def __init__(self, name, tarball):
        self.name = name
        self.tarball = tarball
        self.extracted = False

    def extract(self):
        tar = tarfile.open(self.tarball)
        tar.extractall(path='../')
        self.extracted = True

    def build(self):
        if not self.extracted:
            self.extract()

        os.chdir(self.name)
        os.system("make")
        os.chdir("..")

if __name__ == "__main__":
